INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261018-boston-winter-guide-ev1', 'bd-20261018-boston-winter-guide', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'In-depth explainer drafted from official sources; awaiting editor approval', '2026-10-18T19:30:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261018-uk-politics-explained', 'uk-politics-explained-prime-minister-andy-burnham-cabinet-budget-2026', 'newsroom', 'analysis', 'uk', 'EDITORIAL_REVIEW', 0, 'UK politics explained (autumn 2026): who''s in charge and what''s next', 'Andy Burnham leads a reshaped Labour government heading into Chancellor John Healey''s first Budget on Oct. 28.', 'Andy Burnham is the UK''s prime minister, leading a Labour government after taking office on July 20, 2026, following Keir Starmer''s resignation. His chancellor, John Healey, will deliver the government''s first Budget on Wednesday, Oct. 28, alongside a fresh forecast from the Office for Budget Responsibility. The big questions now are how the government pays for its promises while sticking to its fiscal rules, and whether Labour''s recent rise in the polls holds.

## Who is the UK prime minister right now?

The GOV.UK ministers page lists Andy Burnham as Prime Minister, First Lord of the Treasury, Minister for the Civil Service and Minister for the Union.

Burnham became prime minister on July 20, 2026, after meeting King Charles III at Buckingham Palace, according to AFP. He was previously mayor of Greater Manchester for about a decade and had served in the cabinets of Tony Blair and Gordon Brown, CBS News reported.

## Why did Keir Starmer resign?

Starmer announced his resignation in June 2026 after losing the support of many of his own MPs, according to reporting carried by the Irish Examiner. CBS News pointed to public frustration over the economy and immigration. Starmer had led Labour to a large election win less than two years earlier.

The path to Burnham''s premiership moved quickly:

- **June 19:** Burnham, having stepped down as mayor, won a by-election in Makerfield, Greater Manchester, CBS News reported.
- **June 22:** He was sworn in as MP the same day Starmer announced he would go, the Irish Examiner reported.
- **Mid-July:** Under Labour''s rules, candidates needed the backing of at least 81 MPs. Wes Streeting, seen as his main rival, endorsed Burnham, the Irish Examiner reported.
- **July 20:** Burnham took office, and the government published its ministerial appointments that day.

## Who is in Burnham''s cabinet?

The GOV.UK ministers page lists 23 full cabinet members. Several Starmer-era ministers stayed, while others moved into new roles.

| Role | Minister (per GOV.UK) |
|---|---|
| Prime Minister | Andy Burnham |
| First Secretary of State and Chancellor of the Duchy of Lancaster | Louise Haigh |
| Chancellor of the Exchequer | John Healey |
| Foreign Secretary | Ed Miliband |
| Home Secretary | Shabana Mahmood |
| Defence Secretary | Wes Streeting |
| Health and Social Care Secretary | Yvette Cooper |
| Justice Secretary and Lord Chancellor | Alex Norris |
| Education Secretary | Lucy Powell |
| Work and Pensions Secretary | Pat McFadden |
| Business and Trade Secretary | Jonathan Reynolds |
| Housing, Communities and Local Government Secretary | Angela Rayner |
| Transport Secretary | Heidi Alexander |
| Energy Security and Net Zero Secretary | Miatta Fahnbulleh |
| Culture, Media and Sport Secretary | Lisa Nandy |
| Environment Secretary | Dame Angela Eagle |
| Chief Whip | Anneliese Midgley |
| Leader of the House of Commons | Sir Alan Campbell |
| Leader of the House of Lords | Baroness Smith of Basildon |

The cabinet also includes the secretaries of state for Northern Ireland (Sir Chris Bryant), Scotland (Douglas Alexander) and Wales (Stephen Kinnock), plus Bridget Phillipson as Minister for Women and Equalities. The Attorney General, Ellie Reeves, and Chief Secretary to the Treasury, Emma Reynolds, attend cabinet, according to the July appointments list.

## When is the UK Budget 2026?

The Budget is set for Wednesday, Oct. 28, 2026. Healey confirmed the date in a July 31 letter to Treasury Committee chair Dame Meg Hillier, published on GOV.UK. He asked the Office for Budget Responsibility (OBR) to publish its economic and fiscal forecast the same day.

In a Treasury announcement, Healey framed the Budget around shifting money and decision-making away from Westminster to local areas. He also said it will meet the government''s fiscal rules and keep a buffer against economic shocks, including instability in the Middle East.

## How does the Budget work in Parliament?

UK Parliament''s guidance sets out the stages:

1. The chancellor delivers a statement to the House of Commons reviewing the economy and setting out tax plans, with forecasts from the OBR.
2. A motion lets some changes, such as alcohol and tobacco duties, take effect at 6 p.m. that day.
3. MPs typically debate the Budget resolutions over about four days, with the shadow chancellor responding the day after the statement.
4. A Finance Bill then gives the tax changes permanent legal force. The House of Lords debates it but cannot amend it.

## What shape are the public finances in?

A September 2026 briefing from the House of Lords Library lays out the backdrop:

- The deficit was £130 billion, or 4.2% of GDP, in 2025-26.
- Public sector net debt stood at about £2.985 trillion, or 94.1% of GDP, in July 2026.
- Debt interest cost £109 billion in 2025-26 and is forecast to reach £137 billion by 2030-31.
- Borrowing in the first four months of 2026-27 ran £2.3 billion above the OBR''s March forecast.

The government''s main fiscal rules require the current budget to be in surplus, and net financial liabilities to be falling as a share of GDP, by 2029-30. The Lords Library notes that the OBR''s November 2025 forecast showed £22 billion of headroom against those rules, and cites outside estimates, including from the Resolution Foundation, suggesting that cushion has shrunk considerably. The Burnham government has said it will keep the rules it inherited.

## What are the key issues facing the government?

Reporting from the Associated Press, Al Jazeera and AFP points to a crowded agenda:

- **Cost of living:** Al Jazeera reported that inflation rose to 3.1% in August. AFP reported that Burnham scrapped Starmer''s national digital ID plan and redirected the money to cost-of-living support.
- **Energy prices:** The AP cited fallout from the U.S.-Iran conflict, including disruption to tanker traffic through the Strait of Hormuz.
- **Tax and spending:** The AP said the government faces choices on tax rises, spending cuts or both to fund the NHS, social care and higher defence spending.
- **Public services and utilities:** At Labour''s September conference in Liverpool, Burnham proposed a national care service, ending the ban on public ownership of water companies and a publicly owned "Great British Grid," Al Jazeera reported.
- **Housing:** He pledged to lower the deposit needed by first-time buyers, according to Al Jazeera and the AP.
- **Europe:** The AP reported that a planned UK-EU reset summit had slipped to November at the earliest.
- **Immigration:** The AP noted pressure over Starmer-era plans to make permanent settlement harder.

## Where do the parties stand in the polls?

Labour has regained ground since the leadership change, but surveys disagree on how much. Al Jazeera reported in late September that Survation put Labour at 29% and Reform UK at 23%, while YouGov had Reform at 25%, Labour at 24% and the Conservatives at 19%.

The main opposition leaders, according to the Irish Examiner, are Kemi Badenoch for the Conservatives, Nigel Farage for Reform UK, Ed Davey for the Liberal Democrats and Zack Polanski for the Greens.

## When is the next UK general election?

A general election does not have to be held until 2029, the AP reported. Labour''s polling recovery has fueled speculation about an early vote, but Burnham has dismissed the idea, according to the AP.

## Frequently asked questions

### Who is the current UK prime minister?

Andy Burnham of the Labour Party has been prime minister since July 20, 2026, according to AFP and the GOV.UK ministers list. He succeeded Keir Starmer, who announced his resignation in June.

### Who is the UK chancellor in 2026?

John Healey is Chancellor of the Exchequer, according to GOV.UK. He moved to the Treasury in Burnham''s July reshuffle, with Wes Streeting taking over at Defence.

### When is the autumn Budget 2026?

The Budget will be delivered on Wednesday, Oct. 28, 2026, Healey confirmed in a letter published on GOV.UK. The Office for Budget Responsibility will publish its forecast the same day.

### Did Andy Burnham win a general election?

No. Burnham became prime minister by winning the Labour leadership after Starmer stepped down, having first entered Parliament through the Makerfield by-election in June 2026. He has not faced voters nationally as party leader, and the next general election is due by 2029, according to the AP.

### Is there going to be a snap election?

Burnham has played down the prospect, according to the AP and the Irish Examiner. The next general election must take place by 2029.

### What are the UK government''s fiscal rules?

According to the House of Lords Library, the rules require the day-to-day budget to be in surplus and net financial liabilities to be falling as a share of GDP by 2029-30, with welfare spending kept under a cap. The Burnham government has said it will stick with them.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Official_portrait_of_Andy_Burnham_MP_2026_(cropped_3x4).jpg/1280px-Official_portrait_of_Andy_Burnham_MP_2026_(cropped_3x4).jpg', 'Photo: UK Parliament / Wikimedia Commons, CC BY 3.0', 'licensed', 'newsroom', 'content/2026-10-18-guides-long.sql', 6, 0, 'newsroom-assistant', '2026-10-18T19:30:00.000Z', '2026-10-18T19:30:00.000Z');
